import { useState } from 'react';
import type { FormEvent } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: string;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
}

const defaultSettings: ProfileSettings = {
  name: '',
  language: 'ru',
  emailNotifications: true,
};

function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [settings, setSettings] = useState<ProfileSettings>(initialSettings ?? defaultSettings);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave(settings);
  };

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxInputField
        label="Имя"
        required
        value={settings.name}
        onChange={(event) => setSettings({ ...settings, name: event.target.value })}
      />

      <JxSelect
        label="Язык интерфейса"
        options={[
          { value: 'ru', label: 'Русский' },
          { value: 'en', label: 'English' },
        ]}
        value={settings.language}
        onValueChange={(language) => setSettings({ ...settings, language })}
      />

      <JxSwitch
        label="Уведомления на почту"
        checked={settings.emailNotifications}
        onChange={(event) => setSettings({ ...settings, emailNotifications: event.target.checked })}
      />

      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

export default ProfileSettingsForm;

